mapper.select:
select p.post_id, p.post_code, p.post_type, p.post_name, p.status, count(up.user_id) as user_count from sys_post p left join sys_user_post up on p.post_id = up.post_id
and post_code = #{postCode}
and post_name like concat('%',#{postName},'%')
and post_type = #{postType}
and status = #{status}
group by p.post_id
